from typing import List, Dict
import regex as re

class LegacyCodeTokenizer:
    def __init__(self, vocab_path: str):
        self.vocab = self._load_vocab(vocab_path)
        self.legacy_patterns = {
            'cobol': r'(PERFORM|MOVE|IF|END-IF|WORKING-STORAGE)',
            'fortran': r'(SUBROUTINE|INTEGER|REAL|DO|CONTINUE)',
            'vb6': r'(Dim|Sub|Function|End Sub|Private|Public)',
            'rpg': r'(BEGSR|ENDSR|EXSR|CHAIN|READ)'
        }

    def tokenize(self, code: str, language: str) -> List[int]:
        # Apply language-specific preprocessing
        tokens = self._preprocess(code, language)

        # BPE encoding with legacy keyword preservation
        return self._bpe_encode(tokens)

    def _preprocess(self, code: str, lang: str) -> List[str]:
        pattern = self.legacy_patterns.get(lang, r'\w+')
        return re.findall(pattern, code, re.IGNORECASE)
